const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const jianghanDistrict = ee.Geometry.Point([114.27, 30.58]).buffer(2000); // ~2km buffer around district center
  const date1 = '2020-01-19';
  const date2 = '2020-02-04';

  // 2. Data Acquisition - VIIRS Daily DNB for nighttime lights
  const viirsCol = ee.ImageCollection('NOAA/VIIRS/001/VNP46A2')
    .select('DNB_At_Sensor_Radiance_500m');

  const img1 = viirsCol.filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filterBounds(jianghanDistrict).first();
  const img2 = viirsCol.filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filterBounds(jianghanDistrict).first();

  // Check data availability
  const hasImg1 = img1 && ee.Image(img1).bandNames().size().getInfo() > 0;
  const hasImg2 = img2 && ee.Image(img2).bandNames().size().getInfo() > 0;

  if (!hasImg1 || !hasImg2) {
    console.log(`Data status: Jan19=${hasImg1}, Feb4=${hasImg2}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get mean radiance values
  const scale = 1000;
  const reducer = ee.Reducer.mean().combine(ee.Reducer.count(), null, true);

  const stats1 = ee.Image(img1).reduceRegion({
    reducer: reducer,
    geometry: jianghanDistrict,
    scale: scale,
    maxPixels: 1e9
  });

  const stats2 = ee.Image(img2).reduceRegion({
    reducer: reducer,
    geometry: jianghanDistrict,
    scale: scale,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('DNB_At_Sensor_Radiance_500m_mean').getInfo();
  const count1 = stats1.get('DNB_At_Sensor_Radiance_500m_count').getInfo();
  const mean2 = stats2.get('DNB_At_Sensor_Radiance_500m_mean').getInfo();
  const count2 = stats2.get('DNB_At_Sensor_Radiance_500m_count').getInfo();

  // Check for valid pixels
  if (count1 === 0 || count2 === 0) {
    console.log(`Valid pixels: Jan19=${count1}, Feb4=${count2}`);
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Validation & Final Answer
  if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log(`Means: Jan19=${mean1}, Feb4=${mean2}`);
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Jan19 mean: ${mean1.toFixed(4)} (pixels: ${count1})`);
  console.log(`Feb4 mean: ${mean2.toFixed(4)} (pixels: ${count2})`);
  console.log(`Difference: ${(mean2 - mean1).toFixed(4)}`);

  // Check if Feb 4 shows lower intensity than Jan 19
  if (mean2 < mean1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
